import catalogue from "./plans.json";

// Typed view of plans.json (generated by scripts/sync-plans.mjs from the backend catalogue). Feature keys are the
// backend's entitlement keys; the labels are how the site says them.

export type FeatureKey =
	| "periodic_billing"
	| "service_issues"
	| "xero_payroll"
	| "job_costs"
	| "reports"
	| "assets"
	| "teams"
	| "gps"
	| "customer_portal"
	| "priority_support";

export type Plan = (typeof catalogue.plans)[number] & {
	features: FeatureKey[];
};

export const plans = catalogue.plans as Plan[];
export const trialPlan = plans.find(
	(plan) => plan.code === catalogue.trialPlan,
) as Plan;
export const storageOveragePerGb = catalogue.storageOveragePerGb;

// Only what differs between plans goes in the comparison; everything else is in every plan.
export const featureLabels: { key: FeatureKey; label: string }[] = [
	{
		key: "periodic_billing",
		label: "One invoice per customer per week, fortnight or month",
	},
	{ key: "xero_payroll", label: "Payroll timesheets sent to Xero" },
	{ key: "service_issues", label: "Complaints and rework tracking" },
	{ key: "job_costs", label: "Extras added on site, job costs and margins" },
	{ key: "teams", label: "Teams" },
	{ key: "reports", label: "Reports" },
	{ key: "assets", label: "Vehicles and equipment, with what is due when" },
	{ key: "customer_portal", label: "Customer portal" },
	{ key: "gps", label: "Live map and location history" },
	{ key: "priority_support", label: "Priority support" },
];

export const everyPlan =
	"jobs and recurring jobs, quotes, scheduling, the field app, checklists and photos, completion reports, GST invoices with Xero, hours export and data export.";

const nzd = new Intl.NumberFormat("en-NZ", {
	style: "currency",
	currency: "NZD",
	minimumFractionDigits: 0,
});

// "NZ$49" — whole dollars on the plan cards; the catalogue only has whole-dollar prices.
export function money(amount: string): string {
	return `NZ${nzd.format(Number(amount)).replace("NZ", "")}`;
}

export function hasFeature(plan: Plan, key: FeatureKey): boolean {
	return plan.features.includes(key);
}
